// .vercel-shared-src/src/server/services/customers/customer-service.ts
function displayEmail(user) {
  const email = user?.email?.trim();
  return email ? email : null;
}
async function listAdminCustomers(query) {
  const { rows, total } = await listCustomerProfiles(query);
  const userIds = rows.map((row) => row.userId);
  const counts = await countOrdersForUsers(userIds);
  const countByUser = new Map(
    counts.map((row) => [row.userId, Number(row.value)])
  );
  const supabase = createServiceRoleClient();
  const emails = await Promise.all(
    userIds.map(async (userId) => {
      const { data: data2, error } = await supabase.auth.admin.getUserById(userId);
      if (error || !data2.user) return [userId, null];
      return [userId, displayEmail(data2.user)];
    })
  );
  const emailByUser = new Map(emails);
  const data = rows.map((row) => ({
    userId: row.userId,
    firstName: row.firstName,
    lastName: row.lastName,
    phone: row.phone,
    email: emailByUser.get(row.userId) ?? null,
    createdAt: row.createdAt.toISOString(),
    orderCount: countByUser.get(row.userId) ?? 0
  }));
  return { data, pagination: paginationMeta(query.page, query.pageSize, total) };
}

