// .vercel-shared-src/src/server/services/cart/mappers.ts
function mapCartItem(row) {
  const unitPrice = row.livePrice;
  const unitPriceMinor = moneyToMinor(unitPrice);
  const lineMinor = lineTotalMinor(unitPriceMinor, row.quantity);
  const availableUnits = Number(row.availableUnits);
  const catalogVisible = row.productStatus !== "archived" && row.productStatus !== "draft" && row.variantActive !== false;
  return {
    variantId: row.variantId,
    productId: row.productId,
    productName: row.productName,
    productSlug: row.productSlug,
    sku: row.sku,
    size: row.size,
    color: row.color,
    quantity: row.quantity,
    unitPrice,
    unitPriceMinor,
    lineTotal: minorToMoney(lineMinor),
    lineTotalMinor: lineMinor,
    available: catalogVisible && cartLineAvailable(availableUnits, row.quantity)
  };
}
function emptyCart() {
  return {
    id: null,
    itemCount: 0,
    subtotal: "0.00",
    subtotalMinor: 0,
    items: []
  };
}
function mapCart(cartId, items) {
  const subtotalMinor = items.reduce((sum, item) => sum + item.lineTotalMinor, 0);
  return {
    id: cartId,
    itemCount: items.reduce((sum, item) => sum + item.quantity, 0),
    subtotal: minorToMoney(subtotalMinor),
    subtotalMinor,
    items
  };
}

// .vercel-shared-src/src/server/services/cart/cart-service.ts
function requirePurchasableVariant(variant) {
  if (!variant || variant.productStatus !== "active" || variant.isActive !== true) {
    throw notFoundError("VARIANT_UNAVAILABLE", "This variant is not available.");
  }
  return variant;
}
async function loadCartDto(userId) {
  const cart = await findActiveCartByUserId(userId);
  if (!cart) return emptyCart();
  const lines = await listCartLines(userId);
  return mapCart(cart.id, lines.map(mapCartItem));
}
var getCart = cache(async (userId) => {
  return loadCartDto(userId);
});
async function addCartItem(userId, variantId, quantity) {
  const variant = requirePurchasableVariant(
    await findPurchasableVariant(variantId)
  );
  const unitPrice = toMoneyString(variant.price);
  const db = getDb();
  const upserted = await db.transaction(async (tx) => {
    const cart = await getOrCreateActiveCart(userId, tx);
    return upsertCartItemQuantity(
      cart.id,
      variantId,
      quantity,
      unitPrice,
      tx
    );
  });
  if (!upserted) {
    throw unprocessableError(
      "CART_QUANTITY_LIMIT",
      "You already have the maximum quantity of this variant in your bag."
    );
  }
  logger.info("cart.item_added", { resourceId: variantId });
  return loadCartDto(userId);
}
async function updateCartItem(userId, variantId, quantity) {
  const variant = requirePurchasableVariant(
    await findPurchasableVariant(variantId)
  );
  const unitPrice = toMoneyString(variant.price);
  const updated = await replaceCartItemQuantity(
    userId,
    variantId,
    quantity,
    unitPrice
  );
  if (!updated) {
    throw notFoundError("CART_ITEM_NOT_FOUND", "That item is not in your bag.");
  }
  logger.info("cart.item_updated", { resourceId: variantId });
  return loadCartDto(userId);
}
async function removeCartItem(userId, variantId) {
  const removed = await deleteCartItemForUser(userId, variantId);
  if (!removed) {
    throw notFoundError("CART_ITEM_NOT_FOUND", "That item is not in your bag.");
  }
  logger.info("cart.item_removed", { resourceId: variantId });
  return loadCartDto(userId);
}
async function clearCart(userId) {
  await clearCartItemsForUser(userId);
  logger.info("cart.cleared");
  return loadCartDto(userId);
}

