// src/routes/checkout.ts
import { Router as Router17 } from "express";

// .vercel-shared-src/src/server/services/checkout/checkout-service.ts
async function loadDetail2(orderId, db) {
  const order = await findOrderById(orderId, db);
  if (!order) {
    throw notFoundError("ORDER_NOT_FOUND", "Order not found.");
  }
  const items = await listOrderItems(orderId, db);
  const payment = await findPaymentForOrder(orderId, db);
  return mapOrderDetail(order, items, payment);
}
async function prepareLines(userId, db) {
  const lines = await listCartLines(userId, db);
  if (lines.length === 0) {
    throw unprocessableError("EMPTY_CART", "Your bag is empty.");
  }
  const prepared = [];
  for (const line3 of lines) {
    const variant = await findPurchasableVariant(line3.variantId, db);
    if (!variant || variant.productStatus !== "active" || variant.isActive !== true) {
      throw unprocessableError(
        "CHECKOUT_UNAVAILABLE",
        "A product in your bag is no longer available."
      );
    }
    const availableUnits = Number(variant.availableUnits);
    if (!cartLineAvailable(availableUnits, line3.quantity)) {
      throw conflictError(
        "INSUFFICIENT_STOCK",
        "Not enough stock to check out. Update quantities in your bag."
      );
    }
    const unitPrice = toMoneyString(variant.price);
    const unitPriceMinor = moneyToMinor(unitPrice);
    const lineMinor = lineTotalMinor(unitPriceMinor, line3.quantity);
    prepared.push({
      variantId: variant.variantId,
      productId: variant.productId,
      productName: variant.productName,
      sku: variant.sku,
      size: variant.size,
      color: variant.color,
      quantity: line3.quantity,
      unitPrice,
      totalPrice: minorToMoney(lineMinor),
      lineMinor
    });
  }
  const subtotalMinor = prepared.reduce((sum, line3) => sum + line3.lineMinor, 0);
  return {
    prepared,
    subtotal: minorToMoney(subtotalMinor),
    total: minorToMoney(subtotalMinor)
  };
}
async function createCheckoutOrder(userId, input, tx) {
  const shipping = await findAddressForUser(userId, input.addressId, tx);
  if (!shipping) {
    throw notFoundError("ADDRESS_NOT_FOUND", "Shipping address was not found.");
  }
  const billingRow = input.billingAddressId ? await findAddressForUser(userId, input.billingAddressId, tx) : shipping;
  if (!billingRow) {
    throw notFoundError("ADDRESS_NOT_FOUND", "Billing address was not found.");
  }
  const { prepared, subtotal, total } = await prepareLines(userId, tx);
  const shippingSnap = snapshotAddress(shipping);
  const billingSnap = snapshotAddress(billingRow);
  let order = null;
  for (let attempt = 0; attempt < 5 && !order; attempt += 1) {
    try {
      order = await insertOrder(
        {
          orderNumber: generateOrderNumber(),
          userId,
          status: "pending",
          paymentStatus: "pending",
          fulfillmentStatus: "unfulfilled",
          subtotal,
          discountAmount: "0.00",
          shippingAmount: "0.00",
          taxAmount: "0.00",
          totalAmount: total,
          currency: "INR",
          shippingAddressSnapshot: shippingSnap,
          billingAddressSnapshot: billingSnap,
          idempotencyKey: input.idempotencyKey
        },
        tx
      );
    } catch (error) {
      if (isUniqueViolation(error)) {
        const existing = await findOrderByIdempotency(
          userId,
          input.idempotencyKey,
          tx
        );
        if (existing) {
          return loadDetail2(existing.id, tx);
        }
        continue;
      }
      throw error;
    }
  }
  if (!order) {
    throw conflictError("ORDER_NUMBER_CONFLICT", "Could not allocate an order number.");
  }
  const items = await insertOrderItems(
    prepared.map((line3) => ({
      orderId: order.id,
      productId: line3.productId,
      variantId: line3.variantId,
      productNameSnapshot: line3.productName,
      skuSnapshot: line3.sku,
      sizeSnapshot: line3.size,
      colorSnapshot: line3.color,
      unitPrice: line3.unitPrice,
      quantity: line3.quantity,
      totalPrice: line3.totalPrice
    })),
    tx
  );
  for (const item of items) {
    if (!item.variantId) continue;
    await reserveInventory(
      item.variantId,
      item.quantity,
      {
        actorId: userId,
        referenceType: INVENTORY_REF_RESERVE,
        referenceId: item.id,
        notes: `Checkout ${order.orderNumber}`
      },
      tx
    );
  }
  await insertStatusHistory(
    {
      orderId: order.id,
      oldStatus: null,
      newStatus: "pending",
      changedBy: userId,
      notes: "Checkout created. Awaiting payment."
    },
    tx
  );
  await insertPayment(
    {
      orderId: order.id,
      provider: CHECKOUT_PAYMENT_PROVIDER,
      amount: total,
      currency: "INR",
      status: "pending",
      metadata: { phase: "checkout" }
    },
    tx
  );
  await convertActiveCart(userId, tx);
  logger.info("checkout.created", { resourceId: order.id, actorId: userId });
  return loadDetail2(order.id, tx);
}
async function checkout(userId, input) {
  const existing = await findOrderByIdempotency(userId, input.idempotencyKey);
  if (existing) {
    return attachRazorpayOrderForCheckout(userId, existing.id);
  }
  const db = getDb();
  try {
    const created = await db.transaction(async (tx) => createCheckoutOrder(userId, input, tx));
    return attachRazorpayOrderForCheckout(userId, created.id);
  } catch (error) {
    if (isUniqueViolation(error)) {
      const replay = await findOrderByIdempotency(userId, input.idempotencyKey);
      if (replay) return attachRazorpayOrderForCheckout(userId, replay.id);
    }
    throw error;
  }
}

